      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-vscode-mode\",\n  \"version\": \"0.30.0\",\n  \"description\": \"DSH 上的类 VSCode 编码体验：Monaco 编辑器（文件页签/QuickOpen/状态栏，可驻 DSH 0.1.5+ 官方右侧 Sidebar 与对话同屏）+ 命令栏（Ctrl+Shift+P）与可扩展指令系统 + VS Code 兼容代码片段（.code-snippets 全局/项目，IntelliSense 展开）+ Agent 编辑差异审查（整文件差异/采纳/拒绝/归档/回滚）+ SVN 集成（侧栏变更面板/日志弹窗/并排差异）+ 语言服务器（LSP）智能（跳转定义/引用/hover/大纲 + VSIX 扩展市场安装），状态持久化到工作区旁车，界面状态（页签/光标/侧栏/编辑 Tab/导航历史）镜像到 DSH home 跨重启恢复\",\n  \"icon\": \"assets/icon.svg\",\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"plugin\",\n    \"vscode\",\n    \"editor\",\n    \"monaco\",\n    \"monaco-editor\",\n    \"diff\",\n    \"diff-review\",\n    \"code-review\",\n    \"diff-viewer\",\n    \"files\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Lenonss/DSH_VsCodeMode.git\"\n  },\n  \"homepage\": \"https://github.com/Lenonss/DSH_VsCodeMode\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Lenonss/DSH_VsCodeMode/issues\"\n  },\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \">=0.1.0-rc.1 <0.3.0-0\"\n  },\n  \"packageManager\": \"pnpm@11.3.0\",\n  \"main\": \"./lib/index.js\",\n  \"files\": [\n    \"lib\",\n    \"assets\",\n    \"locale\",\n    \"skills\",\n    \"src\",\n    \"unity\",\n    \"cordis.patch.yml\"\n  ],\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"~3.18.4\",\n    \"@univerjs/preset-sheets-core\": \"1.2.0\",\n    \"@univerjs/presets\": \"1.2.0\",\n    \"@vscode/ripgrep\": \"^1.18.0\",\n    \"exceljs\": \"4.4.0\",\n    \"fflate\": \"0.8.2\",\n    \"saxes\": \"6.0.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"*\",\n    \"@deepseek-ai/dsh-llm\": \"*\",\n    \"@deepseek-ai/dsh-settings\": \"*\",\n    \"@deepseek-ai/dsh-tools\": \"*\",\n    \"cordis\": \">=4.0.0-rc <5\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\",\n    \"schemastery\": \"^3.18.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.1.6-alpha.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.1.0-rc.8\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.0.1-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"0.0.1-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \"0.1.0-rc.8\",\n    \"@deepseek-ai/dsh-tools\": \"0.0.1-rc.1\",\n    \"@types/node\": \"^24.13.3\",\n    \"@types/react\": \"^18.3.1\",\n    \"@types/react-dom\": \"^18.3.5\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"schemastery\": \"3.18.0\",\n    \"semver\": \"^7.8.5\",\n    \"tsdown\": \"^0.22.14\",\n    \"typescript\": \"^5.9.0\",\n    \"vitest\": \"^3.2.4\"\n  },\n  \"scripts\": {\n    \"build\": \"tsdown && node scripts/check-client-artifacts.mjs lib\",\n    \"build:client\": \"tsdown\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\",\n    \"test\": \"vitest run && node --test tests/nativeOpen.test.mjs\",\n    \"prebuild\": \"node -e \\\"fs.rmSync('lib',{recursive:true,force:true})\\\"\",\n    \"prepare\": \"npm run prebuild && npm run build\",\n    \"pack\": \"npm run prebuild && npm run build && npm pack\",\n    \"vendor:monaco\": \"node scripts/vendor-monaco.mjs\"\n  },\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    }\n  }\n}\n"
